68:   const specialization = getSpecialization({ ap: blade.ap, li: blade.li, ms: disc.ms, st: disc.st, mb: tip.mb, sm: tip.sm });
69:   return {
70:     id: `${core.id}-${blade.id}-${disc.id}-${tip.id}`,
71:     displayName: displayName.trim() || `${core.name} ${blade.name}`,
72:     core,
73:     blade,
74:     disc,
75:     tip,
76:     ap: blade.ap,
77:     li: blade.li,
78:     ms: disc.ms,
79:     st: disc.st,
80:     mb: tip.mb,
81:     sm: tip.sm,
82:     type,
83:     scores,
84:     specialization,
85:   };
86: }
87: 
88: export function getSpecialization(bey) {
89:   const candidates = [
90:     ['Attack', bey.ap / 80, bey.mb / 100],
91:     ['Defense', bey.st / 100, bey.ms / 100],
92:     ['Stamina', bey.sm / 100, bey.st / 100],
93:   ];
94:   const domains = [];
95:   for (const [domain, first, second] of candidates) {
96:     if (Math.max(first, second) >= Math.max(0.7, Math.min(first, second) * 1.25)) domains.push(domain);
97:   }
98:   return domains;
99: }
100: 
101: export function createFighter(bey) {
102:   return {
103:     bey,
104:     energy: bey.sm * 1.2,
105:     maxEnergy: bey.sm * 1.2,
106:     stability: bey.st * 1.8,
107:     maxStability: bey.st * 1.8,
108:     pressure: 0,
109:     passivePressure: 0,
110:     special: 0,
111:     guardStack: 0,
112:     dodgeStack: 0,
113:     combo: 0,
114:     lastAction: null,
115:     repeatCount: 0,
116:     history: [],
117:     adaptationReady: false,
118:     lastTurnImpact: 0,
119:   };
120: }
121: 
122: export function createMatch(playerBey, rivalBey, seed = Math.random()) {
123:   return {
124:     turn: 0,
125:     status: 'active',
126:     winner: null,
127:     finish: null,
128:     instability: 0,
129:     fighters: [createFighter(playerBey), createFighter(rivalBey)],
130:     log: [{ turn: 0, text: 'The stadium gates open. Choose your first move.' }],
131:     seed: (Math.floor(seed * 0xffffffff) >>> 0) || 0x7f4a7c15,
132:   };
133: }
134: 
135: function nextRandom(match) {
136:   let value = match.seed >>> 0;
137:   value ^= value << 13;
138:   value ^= value >>> 17;
139:   value ^= value << 5;
140:   match.seed = value >>> 0;
141:   return match.seed / 0x100000000;
142: }
143: 
144: function typeImpactMultiplier(bey, action) {
145:   let multiplier = 1;
146:   if (bey.type === 'Attack' && ['ATTACK', 'SPECIAL'].includes(action)) multiplier *= 1.15;
147:   if (bey.type === 'Balance') multiplier *= 1.05;
148:   if (bey.specialization.includes('Attack') && ['ATTACK', 'SPECIAL'].includes(action)) multiplier *= 1.04;
149:   const apBonus = Math.max(0, bey.ap - 50) * 0.006;
150:   if (['ATTACK', 'SPECIAL'].includes(action)) multiplier *= 1 + Math.min(0.2, apBonus);
151:   return multiplier;
152: }
153: 
154: function defenseReduction(fighter, action) {
155:   if (action !== 'DEFEND') return 0;
156:   const fatigue = Math.max(0.05, 0.2 - 0.05 * fighter.guardStack);
157:   return clamp(fatigue + (fighter.bey.type === 'Defense' ? 0.2 : 0) + (fighter.bey.type === 'Balance' ? 0.05 : 0), 0.05, 0.4);
158: }
159: 
160: function dodgeEffectiveness(fighter, action) {
161:   if (action !== 'DODGE') return 0;
162:   return clamp(1 - Math.max(0, fighter.dodgeStack - 1) * 0.1, 0.2, 1);
163: }
164: 
165: function getActionBonus(fighter, action) {
166:   const history = fighter.history;
167:   if (history.length >= 4) {
168:     const [a, b, c, d] = history.slice(-4);
169:     if (a === c && b === d && a !== b && action !== a) return 0.05;
170:   }
171:   return 0;
172: }
173: 
174: function pressureResistance(bey) {
175:   const mass = Math.max(0, bey.ms - 70) * 0.005;
176:   const defense = bey.type === 'Defense' ? 0.08 : 0;
177:   return clamp(mass + defense, 0, 0.25);
178: }
179: 
180: function burstChance(impact, attacker, defender, defenderAction, initiative) {
181:   const raw = impact * (attacker.bey.ms / Math.max(8, defender.bey.li)) / 12000;
182:   const liResistance = Math.max(0, defender.bey.li - 50) * 0.007;
183:   const defenderType = defender.bey.type === 'Defense' && defenderAction === 'DEFEND' ? 0.2 : 0;
184:   let chance = (0.008 + raw) * (1 - Math.min(0.35, liResistance + defenderType));
185:   if (defenderAction === 'CHARGE') chance *= 1.2;
186:   if (initiative) chance += 0.05;
187:   return clamp(chance, 0.004, 0.22);
188: }
189: 
190: function endMatch(match, winnerIndex, finish, message) {
191:   match.status = 'complete';
192:   match.winner = winnerIndex;
193:   match.finish = finish;
194:   match.log.push({ turn: match.turn, text: message });
195: }
196: 
197: export function resolveTurn(match, actions) {
198:   if (match.status !== 'active') return match;
199:   if (!Array.isArray(actions) || actions.length !== 2 || actions.some((action) => !ACTIONS.includes(action))) {
200:     throw new Error('A valid action is required from both fighters.');
201:   }
202:   const [left, right] = match.fighters;
203:   const fighters = match.fighters;
204:   const messages = [];
205:   const turn = match.turn + 1;
206:   match.turn = turn;
207:   match.instability = Math.min(60, match.instability + 1);
208:   const actionBonus = fighters.map((fighter, index) => getActionBonus(fighter, actions[index]));
209:   const dodgeEffect = fighters.map((fighter, index) => dodgeEffectiveness(fighter, actions[index]));
210:   let collisionChance = 0.4 + (left.bey.mb + right.bey.mb) / 200;
211:   for (let i = 0; i < 2; i += 1) {
212:     if (actions[i] === 'ATTACK') collisionChance += 0.15;
213:     if (actions[i] === 'DODGE') collisionChance -= 0.25 * dodgeEffect[i];
214:     if (fighters[i].bey.specialization.includes('Attack') && actions[i] === 'ATTACK') collisionChance += Math.min(0.08, Math.max(0, fighters[i].bey.mb - 70) * 0.005);
215:   }
216:   collisionChance = clamp(collisionChance, 0.2, 0.9);
217:   const collision = nextRandom(match) < collisionChance;
218:   const initiative = actions.map((action) => action === 'DODGE' || action === 'CHARGE');
219:   const arenaFactor = Math.max(0.7, 1 - match.instability * 0.005);
220:   const effectiveStability = fighters.map((fighter) => Math.max(1, fighter.bey.st * arenaFactor));
221:   const damageTaken = [0, 0];
222:   const burstRolls = [false, false];
223:   let impacts = [0, 0];
224: 
225:   if (collision) {
226:     messages.push(`Collision! ${Math.round(collisionChance * 100)}% engagement chance paid off.`);
227:     for (let i = 0; i < 2; i += 1) {
228:       const target = 1 - i;
229:       const fighter = fighters[i];
230:       const rival = fighters[target];
231:       const action = actions[i];
232:       const actionMultiplier = { ATTACK: 1.5, DEFEND: 0.8, DODGE: 0.7, CHARGE: 0.5, SPECIAL: 5 }[action];
233:       const momentum = fighter.combo >= 2 ? Math.min(0.15, fighter.combo * 0.05) : 0;
234:       const readBonus = initiative[target] ? 0.08 : 0;
235:       const randomFactor = 0.9 + nextRandom(match) * 0.2;
236:       let impact = fighter.bey.ap * (1 + fighter.bey.mb / 120) * actionMultiplier;
237:       impact *= typeImpactMultiplier(fighter.bey, action) * (1 + momentum + readBonus + actionBonus[i]);
238:       if (fighter.bey.type === 'Stamina' && ['CHARGE'].includes(action)) impact *= 1.05;
239:       impact *= randomFactor;
240:       impacts[i] = impact;
241:       const reduction = defenseReduction(rival, actions[target]);
242:       const dodgePenalty = actions[target] === 'DODGE' ? 0.55 + 0.45 * (1 - dodgeEffect[target]) : 1;
243:       const chargeExposure = actions[target] === 'CHARGE' ? 1.25 : 1;
244:       const staminaResistance = rival.bey.type === 'Stamina' ? 0.92 : 1;
245:       const rawLoss = impact / 38;
246:       damageTaken[target] += rawLoss * (1 - reduction) * dodgePenalty * chargeExposure * staminaResistance;
247:       const stabilityLoss = impact / Math.max(10, effectiveStability[target]) * 0.75;
248:       rival.stability = Math.max(0, rival.stability - stabilityLoss);
249:       let pressure = (impact / Math.max(10, rival.bey.ms)) * 1.8;
250:       if (actions[target] === 'DODGE') pressure *= 0.55;
251:       rival.pressure += pressure;
252:       rival.pressure += rival.passivePressure;
253:       rival.passivePressure = 0;
254:       if (actions[i] === 'SPECIAL') {
255:         const recoil = impact / (Math.max(10, effectiveStability[i]) * 2.7);
256:         damageTaken[i] += recoil * (1 + Math.min(0.15, fighter.combo * 0.05));
257:         fighter.stability = Math.max(0, fighter.stability - recoil * 1.5);
258:       }
259:       if (actions[i] === 'ATTACK' || actions[i] === 'SPECIAL') {
260:         const chance = burstChance(impact, fighter, rival, actions[target], initiative[target]);
261:         burstRolls[target] = nextRandom(match) < chance;
262:         if (burstRolls[target]) messages.push(`${rival.bey.core.name}’s lock gives way!`);
263:       }
264:     }
265:     messages.push(`${left.bey.core.name} dealt ${Math.round(impacts[0])} impact · ${right.bey.core.name} dealt ${Math.round(impacts[1])}.`);
266:   } else {
267:     messages.push(`Near miss — the collision chance was ${Math.round(collisionChance * 100)}%.`);
268:     const rank = (action) => ({ ATTACK: 3, SPECIAL: 3, CHARGE: 2, DEFEND: 1, DODGE: 0 })[action];
269:     let target;
270:     if (rank(actions[0]) !== rank(actions[1])) target = rank(actions[0]) < rank(actions[1]) ? 0 : 1;
271:     else if (left.bey.mb !== right.bey.mb) target = left.bey.mb < right.bey.mb ? 0 : 1;
272:     else target = nextRandom(match) < 0.5 ? 0 : 1;
273:     fighters[target].passivePressure += 3;
274:     messages.push(`${fighters[target].bey.core.name} drifts toward the stadium edge (+3 banked pressure).`);
275:   }
276: 
277:   for (let i = 0; i < 2; i += 1) {
278:     const fighter = fighters[i];
279:     const action = actions[i];
280:     const staminaEfficiency = fighter.bey.type === 'Stamina' ? 0.8 : 1;
281:     const specialtyDrain = Math.max(0, fighter.bey.sm - 70) * 0.004;
282:     const baseDrain = (1 + fighter.bey.mb / 80) * staminaEfficiency * Math.max(0.6, 1 - specialtyDrain);
283:     let pressureDrain = fighter.pressure > 70 ? fighter.pressure / 50 : 0;
284:     if (fighter.bey.type === 'Balance') pressureDrain *= 0.95;
285:     damageTaken[i] += baseDrain + pressureDrain;
286:     fighter.energy = Math.max(0, fighter.energy - damageTaken[i]);
287:     if (action === 'CHARGE') {
288:       const gain = fighter.bey.type === 'Stamina' ? 18.75 : 15;
289:       fighter.special = Math.min(100, fighter.special + gain);
290:       messages.push(`${fighter.bey.core.name} charges ${Math.round(gain)} special energy.`);
291:     } else if (action === 'SPECIAL') {
292:       fighter.special = 0;
293:       messages.push(`${fighter.bey.core.name} unleashes a high-risk special!`);
294:     }
295:     if (action === 'DEFEND') fighter.guardStack += 1;
296:     else fighter.guardStack = 0;
297:     if (action === 'DODGE') fighter.dodgeStack += 1;
298:     else fighter.dodgeStack = 0;
299: 
300:     const connectedAttack = collision && ['ATTACK', 'SPECIAL'].includes(action);
301:     if (connectedAttack && impacts[i] >= impacts[1 - i] * 0.8) fighter.combo = Math.min(3, fighter.combo + 1);
302:     else if (!connectedAttack || !collision) fighter.combo = 0;
303:     fighter.history.push(action);
304:     if (fighter.history.length > 12) fighter.history.shift();
305:     fighter.lastAction = action;
306:     fighter.repeatCount = action === fighter.lastAction ? fighter.repeatCount + 1 : 1;
307:     fighter.lastTurnImpact = impacts[i];
308:   }
309: 
310:   // Simultaneous defeats are draws; otherwise burst > ring-out > spin in that order.
311:   const burstLosers = burstRolls.map((bursted, index) => bursted ? index : -1).filter((index) => index >= 0);
312:   if (burstLosers.length === 2) endMatch(match, null, 'double-burst', 'Both locks fail at once — the match is a draw!');
313:   else if (burstLosers.length === 1) endMatch(match, 1 - burstLosers[0], 'burst', `${fighters[burstLosers[0]].bey.core.name} bursts! ${fighters[1 - burstLosers[0]].bey.core.name} takes the match.`);
314:   else {
315:     const ringOuts = fighters.map((fighter, index) => {
316:       if (fighter.pressure <= 120) return false;
317:       const excess = fighter.pressure - 120;
318:       const chance = clamp(0.18 + excess * 0.009 - pressureResistance(fighter.bey), 0.08, 0.72);
319:       return nextRandom(match) < chance;
320:     });
321:     const ringLosers = ringOuts.map((out, index) => out ? index : -1).filter((index) => index >= 0);
322:     if (ringLosers.length === 2) endMatch(match, null, 'double-ring-out', 'Both Beyblades leave the stadium — it’s a draw!');
323:     else if (ringLosers.length === 1) endMatch(match, 1 - ringLosers[0], 'ring-out', `${fighters[ringLosers[0]].bey.core.name} is knocked out of the ring!`);
324:     else {
325:       const exhausted = fighters.map((fighter, index) => fighter.energy <= 0 ? index : -1).filter((index) => index >= 0);
326:       if (exhausted.length === 2) endMatch(match, null, 'double-spin-out', 'Both Beyblades run out of spin — draw!');
327:       else if (exhausted.length === 1) endMatch(match, 1 - exhausted[0], 'spin', `${fighters[exhausted[0]].bey.core.name} runs out of spin!`);
328:       else if (turn >= 40) {
329:         const scores = fighters.map((fighter) => fighter.energy + fighter.stability * 0.15 - fighter.pressure * 0.2);
330:         if (Math.abs(scores[0] - scores[1]) < 0.01) endMatch(match, null, 'time-limit-draw', 'The arena seals at turn 40 — a judge calls a draw.');
331:         else endMatch(match, scores[0] > scores[1] ? 0 : 1, 'time-limit', `${fighters[scores[0] > scores[1] ? 1 : 0].bey.core.name} is outlasted at the turn limit.`);
332:       }
333:     }
334:   }
335: 
336:   match.log.push({ turn, text: messages.join(' ') });
337:   if (match.log.length > 30) match.log.splice(1, match.log.length - 30);
338:   return match;
339: }
340: 
341: export function chooseAiAction(match, aiIndex = 1) {
342:   const ai = match.fighters[aiIndex];
343:   const player = match.fighters[1 - aiIndex];
344:   const options = ACTIONS.filter((action) => action !== 'SPECIAL' || ai.special >= 100);
345:   const recent = player.history.slice(-3);
346:   const predicted = recent.length ? recent[recent.length - 1] : 'ATTACK';
347:   if (ai.special >= 100 && (player.energy < player.maxEnergy * 0.48 || player.lastAction === 'CHARGE' || player.pressure > 75)) return 'SPECIAL';
348:   if (ai.energy < ai.maxEnergy * 0.28) {
349:     if (ai.bey.type === 'Stamina' && ai.special < 100) return 'CHARGE';
350:     return predicted === 'ATTACK' || predicted === 'SPECIAL' ? 'DODGE' : 'DEFEND';
351:   }
352:   if (ai.special < 100 && ai.energy > 15 && (ai.special <= 70 && (match.turn % 6 === 2 || (ai.bey.type === 'Stamina' && match.turn % 5 === 1)))) return 'CHARGE';
353:   if (player.special >= 75 && ['ATTACK', 'SPECIAL'].includes(predicted)) return 'DODGE';
354:   if (player.pressure > 85) return 'ATTACK';
355:   if (predicted === 'CHARGE' && ai.bey.ap > 35) return 'ATTACK';
356:   if (ai.bey.type === 'Attack' || ai.bey.ap >= 50) return match.turn % 4 === 0 ? 'DODGE' : 'ATTACK';
357:   if (ai.bey.type === 'Defense') return ['ATTACK', 'DEFEND', 'ATTACK', 'DODGE'][match.turn % 4];
358:   if (ai.bey.type === 'Stamina') return ['ATTACK', 'CHARGE', 'DEFEND', 'ATTACK', 'DODGE'][match.turn % 5];
359:   return options[(match.turn + recent.length) % options.length];
360: }
361: 
362: export function generateRival(seed = Date.now()) {
363:   const random = (() => {
364:     let state = (seed >>> 0) || 1;
365:     return () => {
366:       state = (state * 1664525 + 1013904223) >>> 0;
367:       return state / 0x100000000;
368:     };
369:   })();
370:   const presets = [
371:     ['aetherion', 'B03', 'D02', 'T02', 'Nova'],
372:     ['draknor', 'B06', 'D06', 'T08', 'Rift'],
373:     ['luminara', 'B05', 'D05', 'T07', 'Bulwark'],
374:     ['crysalix', 'B04', 'D04', 'T05', 'Glacier'],
375:     ['voltaris', 'B07', 'D07', 'T01', 'Voltage'],
376:     ['noctyra', 'B02', 'D08', 'T06', 'Phantom'],
377:   ];
378:   const preset = presets[Math.floor(random() * presets.length)];
379:   return buildBeyblade({ coreId: preset[0], bladeId: preset[1], discId: preset[2], tipId: preset[3] }, preset[4]);
380: }
381: 
382: export function simulateMatch(playerBey, rivalBey, policyA, policyB, seed = 1) {
383:   const match = createMatch(playerBey, rivalBey, seed);
384:   for (let i = 0; i < 40 && match.status === 'active'; i += 1) {
385:     const actions = [policyA(match, 0), policyB(match, 1)];
386:     resolveTurn(match, actions);
387:   }
388:   return match;
389: }
390: 
391: export const policies = {
392:   attack: () => 'ATTACK',
393:   defend: () => 'DEFEND',
394:   dodge: () => 'DODGE',
395:   charge: (match, index) => match.fighters[index].special >= 100 ? 'SPECIAL' : 'CHARGE',
396:   adaptive: (match, index) => chooseAiAction(match, index),
397: };
398: 
399: export function allBuilds() {
400:   const builds = [];
401:   for (const core of CORES) for (const blade of BLADES) for (const disc of DISCS) for (const tip of TIPS) {
402:     builds.push(buildBeyblade({ coreId: core.id, bladeId: blade.id, discId: disc.id, tipId: tip.id }));
403:   }
404:   return builds;
405: }

